style.css:
@-moz-document domain("soundcloud.com") {
/* 01 — INFERNO GRID: VISIBLE ORANGE WIREFRAME BACKGROUND
   Two 54-pixel repeating grids with subtle halos plus large light pools.
   Background is attached to the viewport and will not block mouse input. */
html,
body {
  background-color: #180D08 !important;
  color: #FFAB38 !important;
}

body {
  background-image:
    radial-gradient(ellipse 65% 60% at 88% 5%, rgba(255, 110, 0, 0.32), transparent 75%),
    radial-gradient(ellipse 55% 45% at 6% 76%, rgba(255, 129, 4, 0.18), transparent 83%),
    repeating-linear-gradient(90deg, rgba(255, 110, 0, 0.16) 0px, rgba(255, 110, 0, 0.16) 1px, rgba(255, 110, 0, 0.035) 2px, transparent 3px, transparent 54px),
    repeating-linear-gradient(0deg, rgba(255, 110, 0, 0.16) 0px, rgba(255, 110, 0, 0.16) 1px, rgba(255, 110, 0, 0.035) 2px, transparent 3px, transparent 54px),
    linear-gradient(135deg, #180D08 0%, #291509 51%, #180D08 100%) !important;
  background-attachment: fixed !important;
  background-repeat: no-repeat !important;
  min-height: 100vh;
}

#app,
#content,
.l-container,
.l-content,
.l-main {
  background-color: transparent !important;
}
#app { min-height: 100vh; }

/* 02 — HEADER, PLAYER, AND LOW SURFACES */
.header,
.header__inner,
.playControls,
.playControls__bg,
.playControls__inner,
.sound__soundActions,
.commentForm__wrapper,
.volume__sliderBackground {
  background-color: #1A0F0A !important;
  color: #FFAB38 !important;
}

.header,
.playControls__inner {
  border-color: #7E421B !important;
  box-shadow: 0 2px 20px rgba(255, 115, 6, 0.16), 0 0 12px rgba(255, 94, 0, 0.16) !important;
}

/* 03 — RAISED CONTAINERS, MENUS, PANELS, MODALS */
.sc-background-light,
.sc-background-white,
.g-dark-bg,
.g-modal-section,
.modal__modal,
.dialog,
.dropbar__content,
.moreMenu__list,
.profileMenu__list,
.volume__sliderWrapper,
.tabs__tabs,
.tabs__headingContainer,
.listenLogin,
.uploadMain__foot,
.uploadMain__loggedOut,
.uploadMain__chooserContainer,
.commentFormDisabled,
.unreadConversations,
.audibleEditForm__form,
.gritter-item-wrapper,
.g-upsell-container,
.sidebarInfoBox,
.commentItem.m-creatorComment,
.l-fixed-top-one-column > .l-top,
#content > .container > .row,
#footer > .container > .row,
[role="dialog"],
[role="menu"],
[role="listbox"],
[role="tooltip"] {
  background-color: #26160E !important;
  color: #FFAB38 !important;
}

.modal__modal,
.dialog,
.dropbar__content,
.moreMenu__list,
.profileMenu__list,
.sidebarInfoBox,
[role="dialog"],
[role="menu"],
[role="listbox"] {
  border: 1px solid #7E421B !important;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.38),
              0 0 14px rgba(255, 113, 0, 0.16) !important;
}

.modal__modal,
.dialog {
  background-image: linear-gradient(155deg, #321D10, #26160E 75%) !important;
}

.sidebarInfoBox {
  background-image: linear-gradient(145deg, rgba(255, 108, 0, 0.17), transparent 75%) !important;
}

.modal.modalWhiteout {
  background-color: rgba(18, 10, 5, 0.92) !important;
}

/* Volume popover pointer matches the raised panel. */
.volume__sliderWrapper:before,
.volume__sliderWrapper:after {
  border-top-color: transparent !important;
  border-right-color: transparent !important;
  border-bottom-color: #26160E !important;
  border-left-color: #26160E !important;
}

/* 04 — FIRELIGHT TEXT: amber-orange in place of near-white */
/* Body text remains light enough to read over the brighter surfaces. */
body,
#content,
.l-content,
.l-main,
.sc-text,
.sc-text-primary,
.sc-type-medium,
.sc-type-small,
.commentItem__body,
.sound__mainContent,
.listenEngagement {
  color: #FFAB38 !important;
}

h1, h2, h3, h4, h5, h6,
.sc-type-h1,
.sc-type-h2,
.sc-type-h3,
.soundTitle__title,
.soundBadge__title,
.trackItem__trackTitle,
.audibleTile__title,
.g-type-shrinkwrap-large-primary,
.g-type-shrinkwrap-large-secondary {
  color: #FF9B20 !important;
}

.sc-text-secondary,
.sc-text-light,
.soundTitle__username,
.soundBadge__username,
.soundTitle__uploadTime,
.commentBadge__time,
.sc-text-hint,
.sc-text-hint a,
.sc-ministats,
.commentItem__time {
  color: #D68131 !important;
}

.header__navMenu > li > a,
.g-dark a,
a.sc-link-light,
.header__login,
.header__upload {
  color: #FFAB38 !important;
}

.sc-text-link,
.staticPage p a,
.staticPage li a,
.commentItem a {
  color: #FF8919 !important;
}

.sc-text-link:hover,
.staticPage p a:hover,
.staticPage li a:hover,
.commentItem a:hover,
.g-dark a:hover,
a.sc-link-light:hover {
  color: #FFC16B !important;
}

/* 04B — CONSISTENT ORANGE TEXT IN COMMON SOUND/PLAYLIST LABELS */
body p,
body label,
body strong,
body li,
body small,
body time,
.sc-type-h3,
.sc-type-h4,
.sc-type-h5,
.sc-type-h6,
.soundBadge__title,
.soundBadge__username,
.playbackSoundBadge__titleLink,
.playbackSoundBadge__lightLink,
.playableTile__heading,
.playableTile__mainHeading,
.playableTile__username,
.userBadge__username,
.commentItem__username,
.commentItem__content,
.headerMenu__link,
.profileMenu__link,
.sideBar__section,
.sidebarModule__title {
  color: #FFAB38 !important;
}

a:not(.sc-button),
a:visited:not(.sc-button) {
  color: #FF9B27 !important;
}

/* 05 — TOP-LEFT SOUNDCLOUD LOGO: vivid orange with soft neon glow */
/* Filter recolors a white, black, or image-backed logo without altering layout. */
.header__logoLink,
.header__logo > a,
header a[aria-label="SoundCloud"],
header a[title="SoundCloud"] {
  filter: brightness(0) saturate(100%) invert(53%) sepia(97%)
          saturate(4200%) hue-rotate(359deg) brightness(110%) contrast(103%)
          drop-shadow(0 0 5px rgba(255, 98, 0, 0.95))
          drop-shadow(0 0 14px rgba(255, 115, 17, 0.72)) !important;
}

/* Inline SVG logos are also covered when the logo is not image-backed. */
.header__logo svg,
.header__logoLink svg {
  fill: #FF6A00 !important;
  color: #FF6A00 !important;
}
.header__logo svg path,
.header__logoLink svg path,
.header__logo svg use,
.header__logoLink svg use {
  fill: #FF6A00 !important;
}

/* 06 — NAVIGATION AND TABS */
.header__navMenu > li > a.selected,
.header__navMenu > li > a:hover,
.userNav__button.selected {
  background-color: #342014 !important;
  color: #FFC16B !important;
}

.header__navMenu > li > a.selected,
.userNav__button.selected {
  border-bottom-color: #FF6A00 !important;
}

.tabs__tab.active,
.tabs__tab:hover,
[role="tab"][aria-selected="true"] {
  color: #FF8919 !important;
  border-color: #FF6A00 !important;
}

/* 07 — BUTTONS */
.sc-button {
  background-color: #322015 !important;
  color: #FFAB38 !important;
  border-color: #7E421B !important;
  transition: background-color 0.2s ease, color 0.2s ease,
              border-color 0.2s ease, box-shadow 0.2s ease !important;
}

.sc-button:hover {
  background-color: #4D2A16 !important;
  color: #FFC16B !important;
  border-color: #FF8919 !important;
  box-shadow: 0 0 15px rgba(255, 100, 10, 0.26) !important;
}

.sc-button-selected,
.sc-button-active,
.sc-button[aria-pressed="true"] {
  border-color: #FF961F !important;
  color: #FFC16B !important;
}

.sc-button-play,
.sc-button-cta {
  background-color: #FF7900 !important;
  border-color: #FF7900 !important;
  color: #180D08 !important;
}

.sc-button-play:hover,
.sc-button-cta:hover {
  background-color: #FFB64C !important;
  border-color: #FFC16B !important;
  color: #180D08 !important;
}

/* 08 — PLAYER, VOLUME, AND INTERACTIVE TRACKS */
.playbackTimeline__progressBackground,
.volume__sliderBackground,
.g-scrollbar,
.g-scrollbar-vertical {
  background-color: #342014 !important;
  border-color: #7E421B !important;
  box-shadow: none !important;
}

.playbackTimeline__progressBar,
.volume__sliderProgress {
  background-color: #FF7F0B !important;
}

.playbackTimeline__progressHandle,
.volume__sliderHandle {
  background-color: #FF8919 !important;
}

.compactTrackListItem.clickToPlay:hover,
.chartTrack:hover,
.trackItem.hover,
.trackItem:hover,
[role="option"]:hover,
[role="menuitem"]:hover {
  background-color: #3E2312 !important;
}

.compactTrackListItem.clickToPlay.active,
.trackItem.active,
.editTrackItem.m-active,
[role="option"][aria-selected="true"] {
  background-color: #4A2712 !important;
  border-left-color: #FF6A00 !important;
}

.compactTrackList__moreLink,
.compactTrackList__moreLink:hover,
.moreActions__button,
.moreActions__group .moreActions__link {
  background-color: #342014 !important;
  color: #FFAB38 !important;
}

/* Keep hover overlays and overflow fades from becoming white. */
.soundBadge__additional,
.compactTrackListItem.clickToPlay:hover .compactTrackListItem__additional,
.compactTrackListItem.clickToPlay.active .compactTrackListItem__additional,
.truncatedUserDescription.m-overflow.m-collapsed .truncatedUserDescription__wrapper:after,
.truncatedAudioInfo.m-overflow.m-collapsed .truncatedAudioInfo__wrapper:after,
.trackItem.hover .trackItem__additional,
.trackItem.active .trackItem__additional,
.editTrackItem.m-active .editTrackItem__additional {
  background: transparent !important;
}

/* 09 — INPUTS, SEARCH, COMPOSERS */
input[type="text"],
input[type="search"],
input[type="email"],
input[type="password"],
input[type="url"],
input[type="number"],
textarea,
select,
.commentForm__input,
.composeTextfield .textfield__input,
.recipientChooser .tokenInput__wrapper,
.tokenInput__wrapper,
.headerSearch__input {
  background-color: #342014 !important;
  color: #FFAB38 !important;
  border-color: #7E421B !important;
}

input::placeholder,
textarea::placeholder {
  color: #BF742D !important;
}

input:focus,
textarea:focus,
select:focus,
a:focus,
button:focus {
  outline-color: #FF9B27 !important;
}

input:focus,
textarea:focus,
select:focus {
  border-color: #FF8919 !important;
  box-shadow: 0 0 0 2px rgba(255, 85, 0, 0.12) !important;
}

.sc-toggle,
.sc-toggle-handle,
.sc-radio-radio {
  background-color: #342014 !important;
  border-color: #7E421B !important;
}

/* 10 — TAGS AND SMALL INDICATORS */
.sc-tag {
  background-color: #2D1B11 !important;
  color: #FFA637 !important;
  border: 1px solid #8B491D !important;
}

.sc-tag:hover {
  background-color: #472711 !important;
  color: #FFD078 !important;
}

.audibleTilePlaceholder:before {
  border-color: #7E421B !important;
}

/* 11 — SCROLLBARS (do NOT hide scrolling or site widgets) */
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background-color: #180D08; }
::-webkit-scrollbar-thumb {
  background-color: #8A431B;
  border-radius: 8px;
  border: 2px solid #180D08;
}
::-webkit-scrollbar-thumb:hover { background-color: #F47E0D; }

/* 12 — OPTIONAL LEGACY EMPTY-STATE IMAGES
   Original image URLs retained. These require external Imgur assets;
   if an image disappears, delete only its corresponding declaration. */
.emptyNetworkPage.emptyAlbums .emptyNetworkPage__image,
.emptyNetworkPage.emptySets .emptyNetworkPage__image {
  background-image: url("https://i.imgur.com/OdBeR5O.png") !important;
}

.emptyNetworkPage.emptyStream .emptyNetworkPage__image {
  background-image: url("https://i.imgur.com/QxrvZef.png") !important;
  background-size: 240px 178px !important;
}

.emptyNetworkPage.emptyTracks .emptyNetworkPage__image,
.trackManager__noTracksImage {
  background-image: url("https://i.imgur.com/ZEvSEKh.png") !important;
}

.emptyNetworkPage.emptyReposts .emptyNetworkPage__image {
  background-image: url("https://i.imgur.com/9v9Yufy.png") !important;
}

.emptyNetworkPage.emptyLikes .emptyNetworkPage__image {
  background-image: url("https://i.imgur.com/wDaSGXl.png") !important;
}

.emptyNetworkPage.emptyStations .emptyNetworkPage__image {
  background-image: url("https://i.imgur.com/Ngb6kIB.png") !important;
  background-size: 200px 200px !important;
}

.emptyNetworkPage.emptyUsers .emptyNetworkPage__image {
  background-image: url("https://i.imgur.com/V1u0tRF.png") !important;
  background-size: 240px 177px !important;
}

.emptyNetworkPage.emptyHistory .emptyNetworkPage__image {
  background-image: url("https://i.imgur.com/FEhyOZz.png") !important;
  background-size: 200px 200px !important;
}

.emptyNetworkPage.emptyAlbums .emptyNetworkPage__image,
.emptyNetworkPage.emptySets .emptyNetworkPage__image,
.emptyNetworkPage.emptyTracks .emptyNetworkPage__image,
.emptyNetworkPage.emptyReposts .emptyNetworkPage__image,
.emptyNetworkPage.emptyLikes .emptyNetworkPage__image,
.trackManager__noTracksImage {
  background-size: 240px 167px !important;
}

.paging-eof:before {
  background: url("https://i.imgur.com/kLcF8wf.png") center center no-repeat !important;
}

/* The legacy Imgur More icon override is intentionally removed in v2.2.
   This lets the site's own icon respond to header color corrections. */

/* 13 — CONSISTENT HEADER ICONS, STATES, AND DROPDOWNS
   Color the controls without inverting avatars or artwork. Do not use a
   global SVG filter; mixed fill/stroke icons would become illegible. */
.header .header__navMenu > li > a,
.header .header__link,
.header .header__right a,
.header .header__right button,
.header .header__userNavUsernameButton,
.header .header__userNavActivitiesButton,
.header .header__userNavMessagesButton,
.header .header__userNavTipsButton,
.header .header__uiEvolutionButton,
.header .userNav__button,
.header .headerSearch__submit,
.header .notificationIcon {
  color: #FFAA3B !important;
}

.header .header__right a:hover,
.header .header__right button:hover,
.header .header__navMenu > li > a:hover,
.header .header__userNavUsernameButton:hover,
.header .headerSearch__submit:hover,
.header .userNav__button:hover {
  color: #FFB54A !important;
  background-color: #3E2312 !important;
}

.header .header__navMenu > li > a.selected,
.header .header__right a.selected,
.header .header__right button.selected,
.header .header__userNavUsernameButton.selected,
.header .userNav__button.selected {
  color: #FFC16D !important;
  background-color: #482913 !important;
  border-bottom-color: #FF7D0A !important;
}

/* Icons drawn with CSS sprites or pseudo-elements. */
.header .notificationIcon:before,
.header .notificationIcon:after,
.header .headerSearch__submit:before,
.header .headerSearch__submit:after,
.header .header__moreButton:before,
.header .header__moreButton:after,
.header .header__userNavActivitiesButton:before,
.header .header__userNavMessagesButton:before,
.header .header__userNavTipsButton:before {
  filter: brightness(0) saturate(100%) invert(64%) sepia(93%)
          saturate(1620%) hue-rotate(355deg) brightness(108%) !important;
}

/* Inline SVGs using strokes or currentColor keep their internal shapes. */
.header a svg,
.header button svg,
.header .notificationIcon svg,
.header .headerSearch__submit svg {
  color: #FFAA3B !important;
}

.header a:hover svg,
.header button:hover svg {
  color: #FFB54A !important;
}

.header a svg [stroke],
.header button svg [stroke] {
  stroke: currentColor !important;
}

.header a svg [fill="currentColor"],
.header button svg [fill="currentColor"] {
  fill: currentColor !important;
}

/* Restore the separate orange identity of the logo. */
.header .header__logoLink,
.header .header__logo > a {
  color: #FF6A00 !important;
}
.header .header__logoLink svg,
.header .header__logo > a svg {
  color: #FF6A00 !important;
  fill: #FF6A00 !important;
}

/* Real menu classes, not just ARIA roles. */
.headerMenu,
.headerMenu.m-light,
.headerMenu__list,
.dropdownMenu,
.dropdownContent__container,
.searchAutocomplete,
.searchMenu,
.profileMenu,
.latestActivities__container,
.unreadConversations__container {
  background-color: #26160E !important;
  color: #FFAB38 !important;
  border-color: #7E421B !important;
}

.headerMenu__link,
.dropdownContent__listItem,
.searchMenu__searchFor a,
.searchAutocomplete a,
.profileMenu a,
.moreMenu a,
.notifications a {
  color: #FFAB38 !important;
}

.headerMenu__link:hover,
.headerMenu__link:focus,
.dropdownContent__listItem:hover,
.searchMenu__searchFor a:hover,
.searchAutocomplete a:hover,
.profileMenu a:hover,
.moreMenu a:hover,
.notifications a:hover {
  color: #FFCD78 !important;
  background-color: #4A2912 !important;
}

.headerSearch__submit,
.headerSearch__input,
.headerSearch {
  border-color: #7E421B !important;
}

.newItemBadge,
.newItems__some {
  color: #FFD18B !important;
  background-color: #C95A0B !important;
}

/* 14 — BOTTOM-PLAYER WAVEFORM-STYLE PROGRESS (CSS-ONLY)
   Uses a compact 160 x 22 px PNG waveform texture embedded in this CSS.
   This is not a real track's audio amplitude waveform. The site continues
   updating the played-width element, revealing more of the colored texture.
   No new elements, JavaScript, remote requests, or width overrides are used.
   Remove this section to restore the regular slim progress bar. */
.playbackTimeline__progressBackground,
.playbackTimeline__progressBar {
  height: 22px !important;
  margin-top: -10px !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  background-color: transparent !important;
  background-repeat: repeat-x !important;
  background-size: 160px 22px !important;
  background-position: left center !important;
}

.playbackTimeline__progressBackground {
  background-image: url("data:image/png;base64,") !important;
}

.playbackTimeline__progressBar {
  background-image: url("data:image/png;base64,") !important;
  filter: drop-shadow(0 0 3px rgba(255, 112, 3, 0.60)) !important;
  transition: width 0.10s linear !important;
}

.playbackTimeline__progressHandle {
  background-color: #FF9C24 !important;
  border-color: #FF9220 !important;
  box-shadow: 0 0 6px rgba(255, 104, 44, 0.95),
              0 0 12px rgba(255, 135, 12, 0.60) !important;
}

.playbackTimeline__progressWrapper:hover .playbackTimeline__progressBar {
  filter: drop-shadow(0 0 5px rgba(255, 130, 0, 0.90)) !important;
}

/* 15 — MATCHING ORANGE PLAYBACK, VOLUME, AND TRACK INDICATORS */
.volume__sliderProgress {
  background-color: #FF7400 !important;
}
.volume__sliderHandle {
  background-color: #FFB048 !important;
  box-shadow: 0 0 8px rgba(255, 141, 10, 0.60) !important;
}
.playbackSoundBadge__titleLink:hover,
.soundTitle__title:hover,
.trackItem__trackTitle:hover {
  color: #FFAF43 !important;
}


/* 16 — UNIFIED HOVER GLOW (EMBER / ORANGE / AMBER)
   Shadows only: no transforms, scaling, fixed positioning, or overlays.
   Keeps clicks, scrolling, and the site's own interactions intact. */

/* Transition interactive controls without applying filters to artwork. */
.header .header__navMenu > li > a,
.header .header__right a,
.header .header__right button,
.header .userNav__button,
.header .headerSearch__submit,
.headerMenu__link,
.profileMenu a,
.moreMenu a,
.dropdownContent__listItem,
.searchAutocomplete a,
.sc-button,
.sc-tag {
  transition: color 0.18s ease, background-color 0.18s ease,
              border-color 0.18s ease, box-shadow 0.18s ease,
              text-shadow 0.18s ease !important;
}

/* Header: warm orange glow, matching menu icon/link states. */
.header .header__navMenu > li > a:hover,
.header .header__navMenu > li > a:focus,
.header .header__right a:hover,
.header .header__right a:focus,
.header .header__right button:hover,
.header .header__right button:focus,
.header .userNav__button:hover,
.header .userNav__button:focus,
.header .headerSearch__submit:hover,
.header .headerSearch__submit:focus {
  color: #FFCA70 !important;
  background-color: #492713 !important;
  border-color: #FF7D0A !important;
  box-shadow: inset 0 -2px 0 #FF7D0A,
              0 0 11px rgba(255, 108, 0, 0.48),
              0 0 22px rgba(255, 151, 20, 0.16) !important;
  text-shadow: 0 0 8px rgba(255, 177, 59, 0.58) !important;
}

/* The brand logo stays ember orange, never orange. */
.header .header__logoLink:hover,
.header .header__logoLink:focus,
.header .header__logo > a:hover,
.header .header__logo > a:focus {
  background-color: transparent !important;
  border-color: transparent !important;
  box-shadow: none !important;
  filter: brightness(0) saturate(100%) invert(53%) sepia(97%)
          saturate(4200%) hue-rotate(359deg) brightness(120%) contrast(103%)
          drop-shadow(0 0 7px rgba(255, 100, 0, 1.0))
          drop-shadow(0 0 19px rgba(255, 130, 25, 0.85)) !important;
}

/* Menus and small clickable items: orange inset edge and soft amber aura. */
.headerMenu__link:hover,
.headerMenu__link:focus,
.profileMenu a:hover,
.profileMenu a:focus,
.moreMenu a:hover,
.moreMenu a:focus,
.dropdownContent__listItem:hover,
.dropdownContent__listItem:focus,
.searchAutocomplete a:hover,
.searchAutocomplete a:focus,
[role="menuitem"]:hover,
[role="menuitem"]:focus,
[role="option"]:hover,
[role="option"]:focus {
  background-color: #4A2814 !important;
  color: #FFCA70 !important;
  box-shadow: inset 3px 0 0 #FF7D0A,
              inset 0 0 14px rgba(255, 151, 20, 0.16),
              0 0 11px rgba(255, 108, 0, 0.20) !important;
}

/* Standard actions: blended orange + orange, no size change. */
.sc-button:hover,
.sc-button:focus {
  border-color: #FF7D0A !important;
  box-shadow: 0 0 0 1px rgba(255, 108, 0, 0.35),
              0 0 12px rgba(255, 108, 0, 0.38),
              0 0 23px rgba(255, 106, 0, 0.14) !important;
  text-shadow: 0 0 7px rgba(255, 179, 107, 0.38) !important;
}

/* Primary play and call-to-action controls: hotter orange outer glow. */
.sc-button-play:hover,
.sc-button-play:focus,
.sc-button-cta:hover,
.sc-button-cta:focus {
  border-color: #FFAB38 !important;
  box-shadow: 0 0 0 1px rgba(255, 146, 47, 0.70),
              0 0 14px rgba(255, 106, 0, 0.75),
              0 0 27px rgba(255, 108, 0, 0.34) !important;
  text-shadow: none !important;
}

/* Tracks: gentle amber/orange edge so lists do not turn into neon boxes. */
.trackItem:hover,
.compactTrackListItem.clickToPlay:hover,
.chartTrack:hover,
.soundBadge:hover {
  background-color: #402411 !important;
  box-shadow: inset 3px 0 0 #FF7D0A,
              0 0 12px rgba(255, 151, 20, 0.17) !important;
}

/* Hovered links glow without a visible outline around entire text blocks. */
.sc-text-link:hover,
.commentItem a:hover,
.trackItem__trackTitle:hover,
.soundTitle__title:hover,
.playbackSoundBadge__titleLink:hover {
  color: #FFC368 !important;
  text-shadow: 0 0 9px rgba(255, 108, 0, 0.43) !important;
}

/* Search and forms: illuminate the border, not the whole input surface. */
.headerSearch__input:hover,
input[type="search"]:hover,
input[type="text"]:hover,
textarea:hover {
  border-color: #E48119 !important;
  box-shadow: 0 0 9px rgba(255, 108, 0, 0.17) !important;
}

.headerSearch__input:focus,
input[type="search"]:focus,
input[type="text"]:focus,
textarea:focus {
  border-color: #FFB54A !important;
  box-shadow: 0 0 0 1px rgba(255, 177, 59, 0.50),
              0 0 13px rgba(255, 108, 0, 0.30) !important;
}

.sc-tag:hover {
  border-color: #FF7D0A !important;
  box-shadow: 0 0 9px rgba(255, 108, 0, 0.35) !important;
}

/* Player controls can be icon buttons that do not have .sc-button. */
.playControls__control:hover,
.playControls__control:focus,
.playControls__play:hover,
.playControls__play:focus,
.playControls__next:hover,
.playControls__prev:hover,
.playControls__repeat:hover,
.playControls__shuffle:hover {
  color: #FFC36C !important;
  filter: drop-shadow(0 0 5px rgba(255, 108, 0, 0.60)) !important;
}

/* 17 — ORANGE HOVER HALO FOR ALBUM, GENRE, AND PLAYLIST COVERS
   Includes the square tiles in "Trending by genre". The glow is drawn
   OUTSIDE the artwork; cover art, typography, and tile sizes stay intact.
   No transforms or pseudo-element overlays needed. */
.playableTile__artworkLink,
.playableTile__artwork,
.playableTile__artwork .sc-artwork,
.playableTile__artworkLink .sc-artwork,
.soundBadge__artwork,
.audibleTile__artwork,
.visualSound__artwork,
.tileGallery .sc-artwork {
  transition: box-shadow 0.22s ease, outline-color 0.22s ease !important;
}

/* The artwork link is the safest outer anchor for the square glow. */
.playableTile:hover .playableTile__artworkLink,
.playableTile__artworkLink:hover,
.playableTile__artworkLink:focus,
.playableTile:hover .playableTile__artwork,
.playableTile__artwork:hover,
.playableTile__artworkLink:hover .sc-artwork,
.playableTile__artworkLink:focus .sc-artwork,
.tileGallery__sliderPanelSlide:hover .playableTile__artworkLink,
.soundBadge:hover .soundBadge__artwork,
.soundBadge__artwork:hover,
.audibleTile:hover .audibleTile__artwork,
.visualSound:hover .visualSound__artwork {
  border-radius: 5px !important;
  box-shadow: 0 0 0 2px #FF7D0A,
              0 0 13px rgba(255, 112, 0, 0.82),
              0 0 27px rgba(255, 160, 28, 0.55) !important;
}

/* Keep genre and album captions visually coordinated on hover. */
.playableTile:hover .playableTile__heading,
.playableTile:hover .playableTile__mainHeading,
.playableTile__heading:hover {
  color: #FFB54A !important;
  text-shadow: 0 0 8px rgba(255, 108, 0, 0.35) !important;
}

/* 18 — FINAL ACCESSIBILITY */
::selection {
  background-color: rgba(255, 108, 0, 0.43);
  color: #FFC16B;
}

@media (prefers-reduced-motion: reduce) {
  .sc-button,
  .header .header__navMenu > li > a,
  .header .header__right a,
  .header .header__right button,
  .header .userNav__button,
  .header .headerSearch__submit,
  .headerMenu__link,
  .profileMenu a,
  .moreMenu a,
  .dropdownContent__listItem,
  .searchAutocomplete a,
  .sc-tag,
  .playableTile__artworkLink,
  .playableTile__artwork,
  .playableTile__artwork .sc-artwork,
  .playableTile__artworkLink .sc-artwork,
  .soundBadge__artwork,
  .audibleTile__artwork,
  .visualSound__artwork,
  .tileGallery .sc-artwork { transition: none !important; }
}
}
